grid = [r + [0] * (20-len(r)) for r in grid]
from collections import Counter
pieces = {}
for name, colors in {'2':{2},'3':{3},'7':{7,5},'8':{8}}.items():
    cells = {(r,c):v for r,row in enumerate(grid) for c,v in enumerate(row) if v in colors}
    minr=min(r for r,c in cells); minc=min(c for r,c in cells)
    norm={(r-minr,c-minc):v for (r,c),v in cells.items()}
    pieces[name]=norm
