def dihedral_orients(piece):
    def transform(reflect, turns):
        out={pos:v for pos,v in piece.items()}
        h=max(r for r,c in out)+1; w=max(c for r,c in out)+1
        if reflect:
            out={(r,w-1-c):v for (r,c),v in out.items()}
        hh,ww=h,w
        for _ in range(turns):
            out={(c,hh-1-r):v for (r,c),v in out.items()}
            hh,ww=ww,hh
        mr=min(r for r,c in out); mc=min(c for r,c in out)
        out={(r-mr,c-mc):v for (r,c),v in out.items()}
        return out
    found={}
    for refl in (False,True):
        for k in range(4):
            out=transform(refl,k)
            found.setdefault(frozenset((r,c,v) for (r,c),v in out.items()), out)
    return list(found.values())

orients={k:dihedral_orients(p) for k,p in pieces.items()}
