def place_orient(o,corner,N=14):
    h=max(r for r,c in o)+1; w=max(c for r,c in o)+1
    dr=0 if corner.startswith('T') else N-h
    dc=0 if corner.endswith('L') else N-w
    return {(r+dr,c+dc):v for (r,c),v in o.items()}
