def rotations_only(piece):
    found={}
    out=dict(piece); h=max(r for r,c in out)+1; w=max(c for r,c in out)+1
    for k in range(4):
        # normalize, retain the values
        mr=min(r for r,c in out); mc=min(c for r,c in out)
        norm={(r-mr,c-mc):v for (r,c),v in out.items()}
